-- All catalog mutations emit committed invalidation hints without private paths.
CREATE TRIGGER event_libraries_insert AFTER INSERT ON libraries BEGIN INSERT INTO change_events(topic,resource_id) VALUES ('libraries',NEW.id); END;
CREATE TRIGGER event_libraries_update AFTER UPDATE ON libraries BEGIN INSERT INTO change_events(topic,resource_id) VALUES ('libraries',NEW.id); END;
CREATE TRIGGER event_libraries_delete AFTER DELETE ON libraries BEGIN INSERT INTO change_events(topic,resource_id) VALUES ('libraries',OLD.id); END;
